input.command:
mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "Freelance Dev Micro SaaS Brief",
  "description": "One-page product brief inventing a micro SaaS for freelance developers: catchy name, problem statement, solution, target users."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "inventor": { "depends_on": [] }
  }
}
EOF
cat > agents/inventor.json << 'EOF'
{
  "name": "Product Inventor",
  "system_prompt": "Micro SaaS inventor for developers. Research pains, ideate simple subscription tools, write crisp product briefs.",
  "assignment": "Search the web for real pain points of freelance developers. Invent a micro SaaS product solving one. Write a one-page product brief with catchy name, problem statement, proposed solution, target user.",
  "expected_output": "Product name, pain solved, target user summary, where you saved the full brief.",
  "capabilities": []
}
EOF

cat > config.json << 'EOF'
{
  "name": "User Personas",
  "description": "Three detailed user personas for the Freelance Dev Micro SaaS product. Each includes name, role, daily workflow, biggest frustration, and how the product helps, formatted as structured profiles."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "persona_creator": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Competitive Landscape Analysis",
  "description": "Fictional analysis of 4 invented competitors for the freelance dev micro SaaS, including names, pricing, strengths, weaknesses, and product positioning."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "analyst": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Feature Priority Matrix",
  "description": "Prioritized feature matrix combining user persona needs and competitive gaps for Freelance Dev Micro SaaS. Table with Feature, Priority (Must-Have, Should-Have, Nice-to-Have), Persona Served, Competitive Advantage."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "prioritizer": { "depends_on": [] }
  }
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "Pricing Strategy",
  "description": "3-tier pricing strategy (free, pro, team) including tier names, monthly prices, features, usage limits, target personas, and rationale based on competitive analysis."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "pricing_strategist": { "depends_on": [] }
  }
}
EOF
cat > agents/pricing_strategist.json << 'EOF'
{
  "name": "Pricing Strategist",
  "system_prompt": "SaaS pricing expert for micro-SaaS tools aimed at freelance developers. Design tiered pricing structures that balance competitiveness, value, and revenue.",
  "assignment": "Read the competitive landscape analysis from the previous step. Design a 3-tier pricing strategy: free, pro, team. For each tier specify: name, monthly price, included features, usage limits, target persona. Include a brief rationale for the overall structure.",
  "expected_output": "Summary of the pricing strategy: tier details, rationale, and where you saved the full design (e.g., pricing_strategy.md).",
  "capabilities": []
}
EOF

cat > config.json << 'EOF'
{
  "name": "Revenue Projection",
  "description": "12-month revenue projection spreadsheet as a markdown table. Columns: Month, Free Users, Pro Users, Team Users, MRR, Cumulative Revenue. Based on user growth assumptions and 3-tier pricing."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "projector": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Launch Checklist",
  "description": "Detailed launch checklist grouped into Pre-Launch (weeks 1-2), Launch Week, and Post-Launch (weeks 3-4) phases. Integrates feature priorities and revenue milestones for Freelance Dev Micro SaaS."
}
EOF

